def criar_horarios(apps, schema_editor):
    Nivel = apps.get_model('core', 'Nivel')
    HorarioAula = apps.get_model('core', 'HorarioAula')
    Recesso = apps.get_model('core', 'Recesso')

    for numero, dia, inicio, fim, rotulo, link in HORARIOS:
        HorarioAula.objects.create(
            nivel=Nivel.objects.get(numero=numero),
            dia_semana=dia,
            hora_inicio=inicio,
            hora_fim=fim,
            rotulo=rotulo,
            link_meet=link,
        )
    Recesso.objects.create(
        descricao='Férias de julho', inicio=date(2026, 7, 1), fim=date(2026, 7, 31)
    )


